Q: Get picture from HttpClient A: <p>This is a simple demo UWP application for downloading an image file.
Just paste the image URL link and press the download button to download the desired the image file.</p>
<p><strong>MainPage.xaml</strong></p>
<pre><code>&lt;Page
    x:Class=&quot;HttpDownloader.MainPage&quot;
    xmlns=&quot;http://schemas.microsoft.com/winfx/2006/xaml/presentation&quot;
    xmlns:x=&quot;http://schemas.microsoft.com/winfx/2006/xaml&quot;
    xmlns:local=&quot;using:HttpDownloader&quot;
    xmlns:d=&quot;http://schemas.microsoft.com/expression/blend/2008&quot;
    xmlns:mc=&quot;http://schemas.openxmlformats.org/markup-compatibility/2006&quot;
    mc:Ignorable=&quot;d&quot;
    Background=&quot;{ThemeResource ApplicationPageBackgroundThemeBrush}&quot;&gt;

    &lt;Grid&gt;
        &lt;StackPanel&gt;
            &lt;TextBox x:Name=&quot;uriInput&quot;
                     Header=&quot;URI:&quot; PlaceholderText=&quot;Please provide an uri&quot;
                     Width=&quot;300&quot;
                     HorizontalAlignment=&quot;Center&quot;/&gt;
            &lt;Button Content=&quot;Dowload&quot;
                    HorizontalAlignment=&quot;Center&quot;
                    Click=&quot;Button_Click&quot;/&gt;
        &lt;/StackPanel&gt;
    &lt;/Grid&gt;
&lt;/Page&gt;
</code></pre>
<p><strong>MainPage.xaml.xs</strong></p>
<pre><code>using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Runtime.InteropServices.WindowsRuntime;
using System.Threading.Tasks;
using Windows.Foundation;
using Windows.Foundation.Collections;
using Windows.UI.Xaml;
using Windows.UI.Xaml.Controls;
using Windows.UI.Xaml.Controls.Primitives;
using Windows.UI.Xaml.Data;
using Windows.UI.Xaml.Input;
using Windows.UI.Xaml.Media;
using Windows.UI.Xaml.Navigation;
using System.Net.Http;
using System.Net;
using Windows.Storage.Streams;
using Windows.Storage.Pickers;
using Windows.Storage;
using Windows.Graphics.Imaging;
using System.Threading;

// The Blank Page item template is documented at https://go.microsoft.com/fwlink/?LinkId=402352&amp;clcid=0x409

namespace HttpDownloader
{
    /// &lt;summary&gt;
    /// An empty page that can be used on its own or navigated to within a Frame.
    /// &lt;/summary&gt;
    public sealed partial class MainPage : Page
    {
        public MainPage()
        {
            this.InitializeComponent();
        }

        private async void Button_Click(object sender, RoutedEventArgs e)
        {
            HttpClient client = new HttpClient();
            string imageUrl = uriInput.Text;
            try
            {
                using (var cancellationTokenSource = new CancellationTokenSource(50000))
                {
                    var uri = new Uri(WebUtility.HtmlDecode(imageUrl));
                    using (var response = await client.GetAsync(uri, cancellationTokenSource.Token))
                    {
                        response.EnsureSuccessStatusCode();
                        var mediaType = response.Content.Headers.ContentType.MediaType;
                        string fileName = DateTime.Now.ToString(&quot;yyyyMMddhhmmss&quot;);
                        if (mediaType.IndexOf(&quot;jpg&quot;, StringComparison.OrdinalIgnoreCase) &gt;= 0
                            || mediaType.IndexOf(&quot;jpeg&quot;, StringComparison.OrdinalIgnoreCase) &gt;= 0)
                        {
                            fileName += &quot;.jpg&quot;;
                        }
                        else if (mediaType.IndexOf(&quot;png&quot;, StringComparison.OrdinalIgnoreCase) &gt;= 0)
                        {
                            fileName += &quot;.png&quot;;
                        }
                        else if (mediaType.IndexOf(&quot;gif&quot;, StringComparison.OrdinalIgnoreCase) &gt;= 0)
                        {
                            fileName += &quot;.gif&quot;;
                        }
                        else if (mediaType.IndexOf(&quot;bmp&quot;, StringComparison.OrdinalIgnoreCase) &gt;= 0)
                        {
                            fileName += &quot;.bmp&quot;;
                        }
                        else
                        {
                            fileName += &quot;.png&quot;;
                        }

                        // Get the app's local folder.
                        StorageFolder localFolder = Windows.Storage.ApplicationData.Current.LocalFolder;

                        // Create a new subfolder in the current folder.
                        // Replace the folder if already exists.
                        string desiredName = &quot;Images&quot;;
                        StorageFolder newFolder = await localFolder.CreateFolderAsync(desiredName, CreationCollisionOption.ReplaceExisting);
                        StorageFile newFile = await newFolder.CreateFileAsync(fileName, CreationCollisionOption.ReplaceExisting);

                        using (Stream streamStream = await response.Content.ReadAsStreamAsync())
                        {
                            using (Stream streamToWriteTo = File.Open(newFile.Path, FileMode.Create))
                            {
                                await streamStream.CopyToAsync(streamToWriteTo);
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine(&quot;Exception occur&quot;);
                Console.WriteLine(ex.ToString());
            }
        }
    }
}

</code></pre>
<p>You will find the image in this folder.</p>
<p><code>Users/[current user name]/AppData/Local/Packages/[Application package name]/LocalState/Images</code></p>

Q: How to generate a random number from a CodeIgniter&#39; query&#39;s result value A: <p>To generate a random number you can use this snippet:</p>

<pre><code>$count = 10;
$key = '';
$chars = '0123456789';
for($x = 0; $x &lt; $count; $x++) {
  $key = $key.$chars[rand(0, strlen($chars) - 1)];
}

echo $key;
</code></pre>

Q: How to REPLACE some text in a column of qualifying table rows in CodeIgniter A: <p>I  made an example for you that I think works for you.</p>
<p>you need to find and use <code>str_replace</code> for change your note. see example:</p>
<pre><code>      $findText    = 'John Harrison';
      $replaceText = 'Sebastian';

      $this-&gt;db-&gt;select('*');
      $this-&gt;db-&gt;from('test');
      $this-&gt;db-&gt;where('id-note',5);
      $query = $this-&gt;db-&gt;get();
      $result = $query-&gt;result_array();

      foreach($result as $val) {
          $youText   = $val['note'];
          $replace_1 = [&quot;$findText&quot;];
          $replace_2 = [&quot;$replaceText&quot;];
          $result = str_replace($replace_1, $replace_2, $youText);

          $updateText = array(
              'note'=&gt;$result
          );
          $this-&gt;db-&gt;where('id-data',$val['id']);
          $this-&gt;db-&gt;update('info',$updateText);
      }
</code></pre>
